#!/usr/bin/env bash
set -euo pipefail

# Order Confirmation screen (07 mockup): full WhatsApp-handoff success state
# with personalised thank-you, collapsible recap, Continue-on-WhatsApp, and a
# copy/call fallback. Builds on the merged checkout revamp.
#
# Clones into an isolated, branch-named directory ("gowebsite-claude-order-confirmation-revamp") so it can't
# collide with your Codespace's own checkout or leftovers from earlier runs.

REPO_URL="https://github.com/yoosuf0806/go-website.git"
BRANCH="claude/order-confirmation-revamp"
DIR="gowebsite-claude-order-confirmation-revamp"

if [ -d "$DIR" ]; then
  echo "$DIR already exists here (probably from a previous run of this exact script) — remove it first:" >&2
  echo "  rm -rf $DIR" >&2
  exit 1
fi

echo "Cloning fresh main into $DIR..."
git clone "$REPO_URL" "$DIR"
cd "$DIR"
git checkout -b "$BRANCH"

echo "Applying patch..."
base64 -d <<'PATCH_B64' | git am

PATCH_B64

echo
echo "Patch applied cleanly on branch $BRANCH in ./$DIR"
echo "Next steps:"
echo "  cd $DIR"
echo "  git push -u origin $BRANCH"
echo "  Open a PR: https://github.com/yoosuf0806/go-website/compare/main...$BRANCH"
